-- What pharmacies actually pay per unit for each drug (by NDC) -- the true-cost benchmark for the markup story.
-- Auto-generated by scripts/gen_evidence_pages.py: 1,497,925 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("EFFECTIVE_DATE") as year, count(*) as records
from THE_LIBRARY.HEALTH.DRUG_ACQUISITION_COSTS
where "EFFECTIVE_DATE" is not null
group by 1
order by 1
